from common import *
import ae_figures
import nf_figures
import fm_lesson
import diffusion

def build():
 body=sec('ae','AE：自分自身を再構成する',sub('なぜAEを使うのか：正解ラベルなしで特徴を学びたい',p('MNISTの手書き数字は28×28＝784個の画素値です。しかし、線の傾きや丸みなどを捉えれば、もっと少ない数値でも数字の形を表せそうです。AEの出発点は、こうした重要な特徴を、正解ラベルなしでニューラルネットワークに学ばせたいという考えです。人が特徴を一つずつ決めるのは大変で、分類用の正解ラベルがない場合もあります。そこで、入力を小さな表現へ圧縮し、そこから元に戻せるように学習します。「5と答える」のではなく「この画像を描き直す」ことを課題にすれば、入力画像そのものを正解として使えます。細い中央部分を通しても復元できるようにすることで、形を表す情報を残すように促します。これがAEの基本的な発想です。'))+p('Autoencoder（AE）は入力をencoderで潜在表現zへ変換し、decoderで元の入力へ戻します。潜在とは直接観測する入力ではなく、モデル内部で作る表現という意味です。再構成できるように学ぶことで、データの特徴を捉えます。')+ae_figures.architecture()+eq('z = f_\\varphi(x),\\quad \\hat x = g_\\theta(z),\\quad L = \\lVert x-\\hat x\\rVert^2','φはencoder、θはdecoderのパラメータ。例として画素ごとの二乗誤差を足した再構成損失を示す。実際にはデータの性質に応じた損失を使う。')+p('例えば入力[1,0,1]を[0.8,0.1,0.9]へ再構成したなら、二乗誤差の和は0.04+0.01+0.01=0.06です。AEはラベルなしで学べますが、十分大きなネットワークが単純なコピーを覚えるだけでは有用な表現になりません。次元の制約やノイズ除去などの目的を設けます。'))
 body+=sec('vae','VAE：一点の符号から、分布へ',sub('なぜVAEが作られたのか：潜在変数を持つ生成モデルを学習したい',p('AEは入力を復元する方法を学びますが、それだけでは新しいデータを作るための潜在変数を、どんな分布から選べばよいかが決まりません。一方、潜在変数からデータが生まれる確率モデルを作ると、観測から潜在変数を推定する計算が難しくなります。VAEは、推定を担当するencoderと生成を担当するdecoderを用意し、難しい推定を近似しながら両方を勾配で学べるようにしました。圧縮だけでなく、潜在変数の推定と新しいデータの生成を一緒に扱うための方法です。'))+p('例えば手書きの5を復元するだけでなく、いろいろな形の数字を新しく作りたいとします。AEでは、入力を圧縮した点からの復元は練習しますが、適当に選んだ点から何が出るかまでは学習の目的に含まれません。VAEでは入力を一つの点ではなく、平均と広がりを持つ分布へ変換し、そこから選んだ値で復元を練習します。さらに、潜在分布を標準正規分布へ近づける目的を加え、生成時にも値を選べるようにします。')+ae_figures.architecture(True)+p('中央の山は数字のクラス確率ではなく、潜在変数zがどの値を取りやすいかを示す分布です。平均μは山の中心、標準偏差σは広がりを表します。5という正解ラベルは与えず、画像そのものから分布を推定します。')+eq('\\varepsilon\\sim\\mathcal N(0,I),\\quad z = \\mu_\\varphi(x) + \\sigma_\\varphi(x)\\odot\\varepsilon','N(0,I)は各成分の平均0・分散1の正規分布。例えばμ=2、σ=0.5、ε=−1ならz=1.5。ランダムさをεに分離する再パラメータ化により、μとσへ勾配を流せる。')+p('通常はlog σ²を出力してσを正の値に変換します。潜在次元が2ならμとlog σ²をそれぞれ2個出します。同じxからでもεによって異なるzを得られます。'))
 body+=sec('loss','二つの目的を、同時に満たす',eq('\\begin{aligned} L &= \\mathbb E_{q_\\varphi(z\\mid x)}[-\\log p_\\theta(x\\mid z)] \\\\ &\\quad + D_{\\mathrm{KL}}\\!\\left(q_\\varphi(z\\mid x)\\,\\Vert\\,p(z)\\right) \\end{aligned}','第一項は再構成に対応する負の対数尤度。第二項は潜在分布を事前分布p(z)、通常N(0,I)へ近づける制約。これは負のELBOと呼ばれる目的で、データの尤度を間接的に改善する。')+p('KLダイバージェンスは二つの分布の違いを測る量です。0なら分布が一致し、一般に左右を交換すると値が変わるため通常の距離とは異なります。標準正規分布に対する対角ガウスのKLは、成分ごとのμ²+σ²−1−log σ²を半分にして足せます。')+p('再構成を重視しすぎると潜在の分布が使いにくくなり、制約を強めすぎると入力固有の情報が失われます。decoderが強い場合には潜在を使わなくなるposterior collapseも研究課題です。'))
 body+=sec('sampling','学習後は、どこから生成する？',flow([('標準正規分布','z ∼ N(0,I)',BLUE),('学習済みDecoder','θ を固定'),('生成された x','観測分布から出力',ORANGE)],'生成時はencoderを通らず、事前分布から潜在を引いてdecoderへ渡す。')+p('再構成したいときは入力→encoder→decoder、新しく生成したいときは事前分布→decoderです。この経路の違いが、単なる圧縮と生成モデルを結びます。')+table(['用途','使う情報','注意して読む点'],[('潜在空間の探索','zを変えたdecoder出力','一つの座標が必ず人間の概念に対応するとは限らない'),('異常検知','再構成誤差など','未知の異常をよく再構成してしまう場合もある'),('細胞の応答予測','細胞の表現と刺激による変化','生成・予測した状態は実験検証が必要')]))
 body+=refs([('Deep Learning 第14章：Autoencoders','https://www.deeplearningbook.org/contents/autoencoders.html'),('Kingma & Welling, Auto-Encoding Variational Bayes','https://arxiv.org/abs/1312.6114'),('scGen：細胞の刺激応答予測','https://www.nature.com/articles/s41592-019-0494-8')])
 page('vae','AE・VAE — 圧縮から生成へ','モデルの構造','MODEL 06 / LATENT VARIABLES','入力を潜在表現へまとめ、そこから再構成する。VAEは潜在を確率分布として扱い、新しいデータを生成する経路を作ります。',body)
 b=box(25,25,155,65,'ノイズ z','単純な分布',BLUE)+box(265,25,170,65,'生成器 G','画像を作る')+box(510,25,160,65,'生成画像 G(z)', '',ORANGE)+box(25,170,155,65,'本物の画像 x','訓練データ',BLUE)+box(510,170,220,65,'識別器 D','本物らしさのスコア')+line(185,57,257,57)+line(440,57,503,57)+line(590,95,590,161)+line(184,202,502,202)+txt(337,252,'Dを更新する段階と、Gを更新する段階を交互に行う',14)
 body=sec('why','なぜGANが作られたのか',p('複雑な画像の分布を学ぶとき、各画像の確率を計算したり、見えない潜在変数を推定したりする処理が難しくなることがあります。そこで「本物のデータと見分けがつかないものを作れれば、その分布を学べるのではないか」と考えます。GANは、本物と生成物を区別する識別器を学習し、その判定を生成器の学習信号にしました。生成器の厳密な確率密度を直接計算せずに、データを作る能力を学ぶための設計です。'))
 body+=sec('two-networks','二つのネットワークが、相手を変える',p('GAN（generative adversarial network）は生成器Gと識別器Dを組み合わせます。Gはノイズからデータを作り、Dは実データと生成データを見分けます。GはDを通して「どこを変えると本物と判定されやすいか」という勾配を受け取ります。')+figure(svg(b,280,label='GANの二経路と識別器'),'ネットワークの形は固定ではない。画像ならCNN、条件付き生成ならクラスや元画像も入力する。'))
 body+=sec('loss','何を更新するかを分けて考える',eq('\\begin{aligned} L_D &= -\\mathbb E_x[\\log D(x)] \\\\ &\\quad -\\mathbb E_z[\\log(1-D(G(z)))] \\\\ L_G &= -\\mathbb E_z[\\log D(G(z))] \\end{aligned}','Dは本物を1、生成を0と判定するよう学ぶ。Gは生成物をDが1と判定するよう学ぶ。Gには広く使うnon-saturating損失を表示しており、原論文のminimax式そのものとは区別する。')+table(['段階','固定する重み','更新する重み・必要な計算'],[('Dを学習','G','本物と、Gから切り離した生成物でDの損失を下げる'),('Gを学習','D','Dを通った入力への勾配は計算し、それをGへ戻す'),('画像を生成','Gも更新しない','z→G(z)だけ。Dは使わない')])+p('D(G(z))が0.2ならGの損失−log(0.2)≈1.61、0.8なら≈0.22。Gはこの損失を下げる方向へ変わります。Dも変化するため、固定した一つの損失面を下る状況とは異なります。'))
 body+=sec('use','生成と、画像から画像への変換',flow([('ノイズ・条件','z、クラス、元画像',BLUE),('学習済み生成器','Gθ'),('画像','一度の順伝播で生成',ORANGE)],'通常のGANの生成経路。入力条件を与えるconditional GANは、画像変換などへ利用できる。')+p('画像変換では元画像と目標側の画像を用い、見た目やドメインを変えます。超解像では細部をもっともらしく補うことがありますが、生成した細部が元の場面に本当にあったとは限りません。自然さと内容の正確さは別々に評価します。'))
 body+=sec('limits','自然な一枚と、豊かな分布は別',p('生成器が少数の似た画像ばかり出しても、その一枚は自然に見えるかもしれません。これがmode collapse（生成の多様性の崩壊）の問題です。またDが強すぎるなどの理由でGが有効な勾配を得にくい場合があります。損失の値だけで画質・多様性を判断せず、複数の評価を使います。')+p('GANは通常、各画像の厳密な尤度を直接は計算しません。次のNormalizing Flowは可逆性を制約として、密度を計算できる方向から生成を考えます。DiffusionやFlow Matchingは反復的な生成過程を学ぶ別の方向です。'))
 body+=refs([('Generative Adversarial Networks（2014）','https://arxiv.org/abs/1406.2661'),('pix2pix：Image-to-Image Translation（2016）','https://arxiv.org/abs/1611.07004')])
 page('gan','GAN — 生成と識別を競わせる','モデルの構造','MODEL 07 / ADVERSARIAL GENERATION','本物と見分けるモデルを、生成するモデルの学習信号に使う。更新する重みと、勾配が通る経路を分けて見ます。',body)
 body=sec('why','なぜNormalizing Flowを使うのか',p('新しいデータを生成するだけでなく、観測したデータがモデルの分布でどれくらい高い密度を持つかも計算したい場面があります。GANは通常その密度を直接は返さず、VAEは扱うモデルの尤度を近似的な目的で学びます。そこで、密度が分かる単純な分布を、逆に戻せて伸縮率も計算できる変換で複雑にします。Normalizing Flowは、生成と密度計算を両立させるために、ネットワークの変換へ条件を課す方法です。'))
 body+=sec('invertible','演算を重ねて分布を変える。逆の演算で戻れる。',p('Normalizing Flowは、単純な分布の変数zを、可逆な変換gでデータxへ移します。逆関数f=g⁻¹があるので、観測xをzへ戻して確率密度も計算できます。ここでは有限個の可逆層を重ねる離散的なFlowを中心に説明します。')+nf_figures.distributions()+p('Flowの中心は、元に戻せる演算を何段も重ねることです。掛け算には割り算、足し算には引き算を対応させ、逆向きでは最後の演算から取り消します。途中で値を捨てたり、異なる入力を同じ出力へ潰したりすると、一意に戻せなくなります。AEのように次元を小さくするのではなく、通常は同じ次元のまま分布の形を変えます。')+p('上の例のような一様な拡大だけでは、正規分布の形を十分に複雑にはできません。そこで、残した座標に応じて別の座標を非線形に変えたり、座標の役割を交換したりします。実際のモデルでは変形量をニューラルネットワークで計算し、その重みを学習します。'))
 body+=sec('density','変数変換：伸ばすほど密度は下がる',nf_figures.density()+eq('\\log p_X(x) = \\log p_Z(f(x)) + \\log\\lvert\\det J_f(x)\\rvert','Jfは逆変換fが各方向をどれだけ伸縮させるかを表す微分の行列（ヤコビアン）。detは行列式で、体積の倍率を表す。対数を取ると複数層の倍率の積が和になる。')+p('1次元でx=2z+3ならf(x)=(x−3)/2、微分は1/2なのでpX(x)=pZ((x−3)/2)/2。横幅が2倍になる分、密度の高さは半分です。点が多い場所の「確率密度」と、その一点が出る確率は同じではありません。連続値の確率は区間で積分します。'))
 body+=sec('coupling','Coupling層：一部を固定すると逆に戻せる',eq('\\begin{aligned} y_a &= x_a \\\\ y_b &= x_b\\odot\\exp(s(x_a)) + t(x_a) \\\\ x_b &= (y_b-t(y_a))\\odot\\exp(-s(y_a)) \\end{aligned}','入力をaとbへ分け、aはそのまま渡す。aから計算した倍率と移動量でbを変換する。逆変換では残っているaから同じsとtを計算できる。s・t自体のネットワークは可逆でなくてもよい。')+nf_figures.coupling()+p('xₐ=1、xᵦ=2、s(1)=log 2、t(1)=3ならyₐ=1、yᵦ=7。逆は(7−3)/2=2。この層のヤコビアンは三角形になるので、log|det J|はsの成分の和で計算できます。単に可逆なだけでなく、この計算を容易にする設計が重要です。'))
 body+=sec('train-use','何を学び、どこに使う？',p('学習ではデータxを逆変換し、負の対数尤度−log pX(x)を小さくします。生成では基底分布からzを引いてgを通します。分類器と組み合わせてzを変え、別の予測になる画像を探す反実仮想説明にもつながります。')+p('可逆性や密度計算のしやすさは構造の制約になります。厳密な密度を計算できても、未知の異常を必ず低密度と判定できるとは限りません。また画像の離散画素を連続密度で扱う場合はdequantizationなどの扱いも必要です。')+note('Flow Matchingとの関係','連続時間の可逆な流れを使うContinuous Normalizing Flowもある。Flow Matchingはその速度場を学ぶ目的の一つであり、名前が似た無関係な方法でも、すべて同じ学習方法でもない。'))
 body+=refs([('Real NVP：Affine couplingと密度推定','https://arxiv.org/abs/1605.08803'),('Normalizing Flows for Probabilistic Modeling and Inference','https://arxiv.org/abs/1912.02762')])
 page('normalizing-flow','Normalizing Flow — 可逆な変換で分布を結ぶ','モデルの構造','MODEL 08 / INVERTIBLE TRANSFORMATIONS','生成したものを逆にたどれる。変換の伸縮を計算できる。この二つを使って、複雑なデータの密度を学びます。',body)
 diffusion.build()
 fm_lesson.build()
